#!/usr/bin/env node
/**
 * WPZ Studio catalog sync report.
 *
 * Compares the catalog snapshot in the working tree (`_data/wpz_apps.json`,
 * regenerated by fetch-catalog.mjs) against the committed snapshot
 * (`git HEAD` by default) and prints an at-a-glance diff: how many products
 * the catalog went from/to, which are new, removed, changed (price/title/
 * category/icon), or dead (DisplayCatalog fetch failed in the new snapshot).
 *
 * This closes the gap where fetch-catalog rewrites `_data/` but nothing
 * computed the "N→M products / what actually changed" summary a sync commit
 * message is supposed to quote.
 *
 * Usage:
 *   node tools/scripts/sync-report.mjs [--fetch] [--quiet]
 *                                      [--before <git-ref>] [--after <path>]
 *                                      [--json]
 *
 *   --fetch    run tools/fetch-catalog.mjs first (regenerate _data), then report
 *   --before   git rev:path to diff against   (default: HEAD:_data/wpz_apps.json)
 *   --after    working-tree JSON to treat as new state (default: _data/wpz_apps.json)
 *   --json     also write the structured diff to tools/wpz-sync-diff.json (gitignored)
 *   --quiet    summary line only
 *
 * Exits 0 on any successful report; exits 1 only if a fetch/parse it triggers
 * hard-fails. Intended to be safe to run in CI and locally.
 */
import fs from 'node:fs'
import path from 'node:path'
import { execFileSync } from 'node:child_process'
import { fileURLToPath } from 'node:url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const REPO_ROOT = path.resolve(__dirname, '..', '..')
const DATA_REL = '_data/wpz_apps.json'
const FETCH_CATALOG = path.join(REPO_ROOT, 'tools', 'fetch-catalog.mjs')
const DEFAULT_JSON_OUT = path.join(REPO_ROOT, 'tools', 'wpz-sync-diff.json')

const args = process.argv.slice(2)
const has = (f) => args.includes(f)
const val = (f) => { const i = args.indexOf(f); return i === -1 || args[i + 1] === undefined ? null : args[i + 1] }

const quiet = has('--quiet')
const beforeRef = val('--before') || `HEAD:${DATA_REL}`
const afterPath = val('--after') ? path.resolve(REPO_ROOT, val('--after')) : path.join(REPO_ROOT, DATA_REL)

function loadGit(ref) {
  try {
    const out = execFileSync('git', ['-C', REPO_ROOT, 'show', ref], {
      encoding: 'utf8', maxBuffer: 64 * 1024 * 1024
    })
    return JSON.parse(out)
  } catch {
    return []
  }
}

function loadFile(p) {
  try {
    const raw = fs.readFileSync(p, 'utf8')
    return JSON.parse(raw)
  } catch {
    return null
  }
}

const disp = (a) => a.title || a.name || a.productId
const idOf = (a) => String(a.productId || '').toUpperCase()
const norm = (v) => (v == null ? '' : String(v))

const FIELDS = [
  ['title', 'title'],
  ['name', 'name'],
  ['price', 'price'],
  ['category', 'category'],
  ['iconUrl', 'icon']
]

function indexBy(list) {
  const m = new Map()
  for (const a of list) if (a && a.productId) m.set(idOf(a), a)
  return m
}

function main() {
  if (has('--fetch')) {
    execFileSync('node', [FETCH_CATALOG], { stdio: 'inherit', cwd: REPO_ROOT })
  }

  const beforeArr = loadGit(beforeRef)
  const afterArr = loadFile(afterPath)
  if (afterArr === null) {
    console.error(`[sync-report] could not read working catalog at ${afterPath} (run fetch-catalog first)`)
    process.exit(1)
  }

  const before = indexBy(beforeArr)
  const after = indexBy(afterArr)
  const beforeIds = [...before.keys()]
  const afterIds = [...after.keys()]

  const added = afterIds.filter((id) => !before.has(id)).map((id) => after.get(id))
  const removed = beforeIds.filter((id) => !after.has(id)).map((id) => before.get(id))
  const dead = afterArr.filter((a) => a && a.error)

  const changed = []
  for (const id of afterIds) {
    if (!before.has(id)) continue
    const b = before.get(id), a = after.get(id)
    const fields = {}
    for (const [key, label] of FIELDS) {
      if (norm(a[key]) !== norm(b[key])) fields[label] = { from: b[key] ?? null, to: a[key] ?? null }
    }
    if (Object.keys(fields).length) changed.push({ productId: id, name: disp(a), fields })
  }

  const summary = {
    before: { ref: beforeRef, count: beforeArr.length },
    after: { path: afterPath, count: afterArr.length },
    added: added.map((a) => ({ productId: idOf(a), name: disp(a), category: a.category || null, price: a.price || null })),
    removed: removed.map((a) => ({ productId: idOf(a), name: disp(a) })),
    changed,
    dead: dead.map((a) => ({ productId: idOf(a), name: disp(a), error: a.error }))
  }

  // ---- human report ----
  console.log('WPZ Studio catalog sync report')
  console.log(`  committed: ${beforeArr.length} products  (${beforeRef})`)
  console.log(`  working:   ${afterArr.length} products  (${path.relative(REPO_ROOT, afterPath)})`)
  console.log(`  → ${beforeArr.length}→${afterArr.length}   (+${added.length} new, -${removed.length} removed, ${changed.length} changed, ${dead.length} dead)\n`)

  if (!added.length && !removed.length && !changed.length && !dead.length) {
    console.log('No catalog changes detected.')
  } else if (!quiet) {
    if (added.length) {
      console.log('New products:')
      for (const a of added) console.log(`  + ${disp(a)} (${idOf(a)})${a.category ? `  [${a.category}]` : ''}${a.price ? `  ${a.price}` : ''}`)
      console.log('')
    }
    if (removed.length) {
      console.log('Removed products (in committed, gone from working):')
      for (const a of removed) console.log(`  - ${disp(a)} (${idOf(a)})`)
      console.log('')
    }
    if (changed.length) {
      console.log('Changed products:')
      for (const c of changed) {
        const parts = Object.entries(c.fields).map(([f, v]) => `${f} "${v.from ?? '(none)'}" → "${v.to ?? '(none)'}"`)
        console.log(`  ~ ${c.name} (${c.productId}): ${parts.join('; ')}`)
      }
      console.log('')
    }
    if (dead.length) {
      console.log('Unfetchable / possibly unpublished (fetch returned an error):')
      for (const a of dead) console.log(`  ! ${disp(a)} (${idOf(a)}): ${String(a.error).slice(0, 100)}`)
      console.log('')
    }
  }

  if (has('--json')) {
    fs.writeFileSync(DEFAULT_JSON_OUT, JSON.stringify(summary, null, 2) + '\n', 'utf8')
    console.log(`Structured diff written to ${path.relative(REPO_ROOT, DEFAULT_JSON_OUT)}`)
  }

  process.exit(0)
}

main()
